package com.savora.config; import com.savora.model.User; import com.savora.model.Role; import com.savora.repo.UserRepo; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class SeedConfig { @Bean CommandLineRunner seed(UserRepo users,PasswordEncoder enc){return a->{if(users.findByEmail("admin@savora.local").isEmpty()){var u=new User();u.name="Savora Admin";u.email="admin@savora.local";u.password=enc.encode("Admin@123");u.role=Role.ADMIN;users.save(u);}};} }
